it('rejects invalid input for function-valued tool definitions', async () => {
  const registry = new ToolRegistry();
  const schema1 = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
  registry.register(
    () => ({name: 'fn', description: 'd', inputSchema: schema1}),
    async () => 'ok'
  );

  expect(await registry.execute('fn', {})).toMatchObject({
    result: expect.stringMatching(/required.*'a'|'a'.*required/),
  });
});

it('updates validation when function-valued tool definition returns a new schema', async () => {
  const registry = new ToolRegistry();
  let currentSchema: Record<string, unknown> = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};

  registry.register(
    () => ({name: 'fn', description: 'd', inputSchema: currentSchema}),
    async () => 'ok'
  );

  // Initial check
  expect(await registry.execute('fn', {a: 'val'})).toMatchObject({result: 'ok'});

  // Switch to schema2
  const schema2 = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
  currentSchema = schema2;
  expect(await registry.execute('fn', {b: 123})).toMatchObject({result: 'ok'});

  // Rejection based on updated schema
  expect(await registry.execute('fn', {a: 'val'})).toMatchObject({
    result: expect.stringMatching(/required.*'b'|'b'.*required/),
  });
});

