it('rejects invalid input for function-valued tool definitions', async () => {
  const registry = new ToolRegistry();
  const dynamicSchema = {type: 'object', properties: {field: {type: 'string'}}, required: ['field']};
  registry.register(
    () => ({name: 'dynamic', description: 'desc', inputSchema: dynamicSchema}),
    async () => 'ok'
  );

  const response = await registry.execute('dynamic', {});
  expect(response.result).toMatch(/required.*'field'|'field'.*required/);
});

it('updates validation when function-valued tool definition returns a new schema', async () => {
  const registry = new ToolRegistry();
  let currentSchema: Record<string, unknown> = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};

  registry.register(
    () => ({name: 'fn', description: 'd', inputSchema: currentSchema}),
    async () => 'ok'
  );

  const first = await registry.execute('fn', {a: 'val'});
  currentSchema = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
  const second = await registry.execute('fn', {b: 123});
  const third = await registry.execute('fn', {a: 'val'});

  expect({
    first: first.result,
    second: second.result,
    third: third.result,
  }).toMatchObject({
    first: 'ok',
    second: 'ok',
    third: expect.stringMatching(/required.*'b'|'b'.*required/),
  });
});

